const sampleFingerprint = `-- name: SampleFingerprint :one
SELECT fingerprint FROM samples WHERE strategy_id = ? AND kind = ? AND report_id = ?
`

type SampleFingerprintParams struct {
	StrategyID string
	Kind       string
	ReportID   string
}

func (q *Queries) SampleFingerprint(ctx context.Context, arg SampleFingerprintParams) (string, error) {
	row := q.db.QueryRowContext(ctx, sampleFingerprint, arg.StrategyID, arg.Kind, arg.ReportID)
	var fingerprint string
	err := row.Scan(&fingerprint)
	return fingerprint, err
}

const setMetricDefinition = `-- name: SetMetricDefinition :exec
INSERT INTO metric_definitions (strategy_id, name, definition) VALUES (?, ?, ?)
ON CONFLICT (strategy_id, name) DO UPDATE SET definition = excluded.definition
`

type SetMetricDefinitionParams struct {
	StrategyID string
	Name       string
	Definition string
}

func (q *Queries) SetMetricDefinition(ctx context.Context, arg SetMetricDefinitionParams) error {
	_, err := q.db.ExecContext(ctx, setMetricDefinition, arg.StrategyID, arg.Name, arg.Definition)
	return err
}

const touchSeries = `-- name: TouchSeries :exec
INSERT INTO series_catalog(strategy_id, instance_id, kind, series, observed_at) VALUES (?, ?, ?, ?, ?)
ON CONFLICT(strategy_id, instance_id, kind, series) DO UPDATE SET observed_at = excluded.observed_at
WHERE excluded.observed_at > series_catalog.observed_at
`

type TouchSeriesParams struct {
	StrategyID string
	InstanceID string
	Kind       string
	Series     string
	ObservedAt int64
}

func (q *Queries) TouchSeries(ctx context.Context, arg TouchSeriesParams) error {
	_, err := q.db.ExecContext(ctx, touchSeries,
		arg.StrategyID,
		arg.InstanceID,
		arg.Kind,
		arg.Series,
		arg.ObservedAt,
	)
	return err
}
